selector:
/* Labels must not inherit the legacy responsive 1.05 text multiplier or
   different span line heights in host and iframe navigation. */
:is(#keysUnifiedPrototype#keysUnifiedPrototype#keysUnifiedPrototype,.keys-module-screen) .keys-bottom-nav :is(.keys-bottom-tab,.keys-bottom-label)

/* Text-entry controls retain 16 px type on mobile to avoid zoom on focus.
   Checkboxes, calendar controls, numeric steppers and photo pickers keep their geometry. */
#keysUnifiedPrototype#keysUnifiedPrototype#keysUnifiedPrototype :is(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="file"]):not([type="hidden"]),textarea,select)

/* Shared Arbana utility roles still used in chats, reviews, selectors and sheets.
   Normalize the role itself so newly opened views follow the same scale. */
#root :is(.text-10,.text-11)

/* Bottom-sheet type roles match the booking page and Arbana UI kit. */
#keysUnifiedPrototype#keysUnifiedPrototype #keysStayDetails .ksd-sheet,
#keysUnifiedPrototype#keysUnifiedPrototype #keysStayDetails .ksd-sheet :is(p,button,input,span)

